input.old_string:
    // Metadata is bidirectional: echoed back in every Event via Event.Metadata,
    // AND stamped onto every line written to the session log (e.g., bead_id,
    // attempt_id) so external log consumers can correlate.
    //
    // Reserved cross-tool keys:
    //   produces_artifact — caller-declared artifact path or URI produced by the task
    //   media_type        — MIME/media type for produces_artifact
    //
    // The service currently treats metadata as an opaque string map and echoes
    // it; these keys are reserved so DDx/HELIX consumers can agree on artifact
    // semantics without parsing model output. Implemented echo path:
    // service.go ExecuteRequest.Metadata plus service_events.go Event.Metadata.
    Metadata map[string]string
}

input.new_string:
    // Metadata is bidirectional: echoed back in every Event via Event.Metadata,
    // AND stamped onto every line written to the session log (e.g., bead_id,
    // attempt_id) so external log consumers can correlate.
    //
    // Reserved cross-tool keys:
    //   produces_artifact — caller-declared artifact path or URI produced by the task
    //   media_type        — MIME/media type for produces_artifact
    //   role              — mirror of top-level Role (see below); top-level wins on collision
    //   correlation_id    — mirror of top-level CorrelationID; top-level wins on collision
    //
    // The service currently treats metadata as an opaque string map and echoes
    // it; these keys are reserved so DDx/HELIX consumers can agree on artifact
    // semantics without parsing model output. Implemented echo path:
    // service.go ExecuteRequest.Metadata plus service_events.go Event.Metadata.
    //
    // Collision rule for `role` and `correlation_id`: if a caller sets both the
    // top-level field (Role / CorrelationID) and the corresponding Metadata
    // entry, the top-level field wins and the service emits a
    // `MetadataKeyCollision` warning event identifying the offending key. A
    // future contract version may reject this case at the service boundary; for
    // now the warning is the only signal.
    Metadata map[string]string

    // Role tags the call with a caller-defined work classification (e.g.,
    // "implementer", "reviewer", "decomposer"). Day 1 this is observational only:
    // it is echoed into RoutingDecision and Final event metadata and into the
    // session-log header, but it does NOT enter the routing precedence chain
    // (see § Selection precedence). Empty = unset.
    //
    // Normalization: lowercased, alphanumeric plus hyphen only, max 64 chars.
    // Invalid values are rejected pre-dispatch with a typed
    // RoleNormalizationError before any session state opens or any provider
    // dispatches. See § Normalization rules and typed errors.
    Role string
    // CorrelationID joins related calls (e.g., implementer + reviewer + retry
    // attempts of the same bead) for log aggregation and trace-join. Day 1 this
    // is observational only — same echo paths and same routing-neutrality as
    // Role. Empty = unset.
    //
    // Normalization: printable ASCII only (no control chars; whitespace allowed
    // is hyphen, colon, and underscore only), max 256 chars. Invalid values are
    // rejected pre-dispatch with a typed CorrelationIDNormalizationError. See
    // § Normalization rules and typed errors.
    CorrelationID string
}
